def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last = history[-1][0]
    opp_last = history[-1][1]

    if n <= 5:
        return 'C' if opp_last == 'C' else 'D'

    opp_coop = 0
    for h in history:
        if h[1] == 'C':
            opp_coop += 1
    opp_rate = opp_coop / float(n)

    recent_start = n - 15
    if recent_start < 0:
        recent_start = 0

    rec_coop = 0
    rec_len = 0
    for h in history[recent_start:]:
        rec_len += 1
        if h[1] == 'C':
            rec_coop += 1
    rec_rate = rec_coop / float(rec_len) if rec_len > 0 else 0.5

    c_after_c = 0
    c_after = 0
    d_after_c = 0
    d_after = 0

    for i in range(1, n):
        prev_move = history[i - 1][0]
        opp_move = history[i][1]
        if prev_move == 'C':
            c_after += 1
            if opp_move == 'C':
                c_after_c += 1
        else:
            d_after += 1
            if opp_move == 'C':
                d_after_c += 1

    opp_streak = 0
    for h in reversed(history):
        if h[1] == 'D':
            opp_streak += 1
        else:
            break

    prev_my = history[-2][0] if n >= 2 else 'C'

    if opp_rate < 0.22 and rec_rate < 0.30:
        return 'D'
    if rec_rate < 0.10 and opp_streak >= 3:
        return 'D'

    alpha = 2.0
    p_c = (c_after_c + alpha * 0.90) / (c_after + alpha)
    p_d = (d_after_c + alpha * 0.20) / (d_after + alpha)

    if opp_last == 'D':
        if opp_streak >= 2:
            if (opp_rate > 0.70 and rec_rate > 0.60 and n > 50 and
                    opp_streak == 2 and rng.random() < 0.20):
                return 'C'
            return 'D'

        if prev_my == 'D':
            return 'C' if rec_rate > 0.35 else 'D'

        if opp_rate > 0.85 and rec_rate > 0.75 and rng.random() < 0.25:
            return 'C'

        return 'D'

    p_cur = p_c if my_last == 'C' else p_d
    threshold = (1.0 + p_cur) / 3.0
    if p_c - p_d >= threshold:
        action = 'C'
    else:
        action = 'D'

    if (action == 'D' and d_after == 0 and opp_rate > 0.70 and
            rec_rate > 0.70 and n < 65):
        action = 'C'

    if (d_after == 0 and action == 'C' and n >= 65 and
            opp_rate > 0.60 and rec_rate > 0.60 and my_last != 'D'):
        action = 'D'

    if (action == 'D' and my_last == 'D' and opp_last == 'C' and
            d_after == 0 and rec_rate > 0.60 and opp_rate > 0.60):
        return 'C'

    return action
